#pragma once
#include <pxr/base/tf/token.h>
#include <omni/fabric/IToken.h>
#include <carb/cpp/Span.h>

namespace omni
{
namespace fabric
{

struct TfAndFabricImmortalToken
{
    // TODO: Fix temp workaround for cases where the IToken is not available, for example Text Render Delegate plugins.
    TfAndFabricImmortalToken(const char* tok)
        : fabricToken(carb::getCachedInterface<omni::fabric::IToken>() != nullptr ? omni::fabric::Token::createImmortal(tok) : omni::fabric::Token()),
          tfToken(tok, PXR_NS::TfToken::Immortal)
    {
    }

    operator const PXR_NS::TfToken&() const
    {
        return tfToken;
    }

    operator const omni::fabric::Token&() const
    {
        return fabricToken;
    }

    bool operator==(const PXR_NS::TfToken& other) const
    {
        return tfToken == other;
    }

    bool operator==(const omni::fabric::Token& other) const
    {
        return fabricToken == other;
    }

    bool operator!=(const PXR_NS::TfToken& other) const
    {
        return tfToken != other;
    }

    bool operator!=(const omni::fabric::Token& other) const
    {
        return fabricToken != other;
    }

    bool operator==(const TfAndFabricImmortalToken& other) const
    {
        return tfToken == other.tfToken;
    }

    char const* GetText() const
    {
        return tfToken.GetText();
    }

    const std::string& GetString() const
    {
        return tfToken.GetString();
    }

    size_t size() const
    {
        return tfToken.size();
    }

    const omni::fabric::Token fabricToken;
    const PXR_NS::TfToken tfToken;
};

// Non-member comparison operators to allow TfAndFabricImmortalToken on the right side
inline bool operator==(const PXR_NS::TfToken& lhs, const TfAndFabricImmortalToken& rhs)
{
    return lhs == rhs.tfToken;
}

inline bool operator!=(const PXR_NS::TfToken& lhs, const TfAndFabricImmortalToken& rhs)
{
    return lhs != rhs.tfToken;
}

inline bool operator==(const omni::fabric::Token& lhs, const TfAndFabricImmortalToken& rhs)
{
    return lhs == rhs.fabricToken;
}

inline bool operator!=(const omni::fabric::Token& lhs, const TfAndFabricImmortalToken& rhs)
{
    return lhs != rhs.fabricToken;
}

template <typename T>
struct TfAndFabricImmortalTokenAccessor
{
    const T* operator->() const
    {
        return get();
    }

    omni::fabric::Span<const TfAndFabricImmortalToken> allTokens() const
    {
        return omni::fabric::Span<const TfAndFabricImmortalToken>(
            reinterpret_cast<const TfAndFabricImmortalToken*>(get()), sizeof(T) / sizeof(TfAndFabricImmortalToken));
    }

private:
    const T* get() const
    {
        static const T tokens;
        return &tokens;
    }
};

} // namespace fabric
} // namespace omni

#define GET_TF_AND_FABRIC_IMMORTAL_TOKEN_MACRO(_1, _2, NAME, ...) NAME
#define EXPAND_TF_AND_FABRIC_IMMORTAL_TOKEN_ARGS(args) GET_TF_AND_FABRIC_IMMORTAL_TOKEN_MACRO args
#define DECLARE_TF_AND_FABRIC_IMMORTAL_TOKEN(...)                                                                                  \
    EXPAND_TF_AND_FABRIC_IMMORTAL_TOKEN_ARGS((__VA_ARGS__, DECLARE_TF_AND_FABRIC_IMMORTAL_TOKEN_2, DECLARE_TF_AND_FABRIC_IMMORTAL_TOKEN_1))(__VA_ARGS__)

#define DECLARE_TF_AND_FABRIC_IMMORTAL_TOKEN_1(name) const omni::fabric::TfAndFabricImmortalToken name{ #name };

#define DECLARE_TF_AND_FABRIC_IMMORTAL_TOKEN_2(name, value) const omni::fabric::TfAndFabricImmortalToken name{ value };
